372	func sameRefreshDevice(updated, existing ml.DeviceInfo) bool {
373		if updated.Library != existing.Library {
374			return false
375		}
376		if updated.PCIID != "" && existing.PCIID != "" {
377			return strings.EqualFold(updated.PCIID, existing.PCIID)
378		}
379		return updated.DeviceID == existing.DeviceID
380	}
