382	func filterIntegratedGPUs(devices []ml.DeviceInfo) []ml.DeviceInfo {
383		if runtime.GOOS == "darwin" && runtime.GOARCH == "arm64" {
384			return devices
385		}
386	
387		allow, explicit := integratedGPUAdmission()
388		filtered := devices[:0]
389		for _, device := range devices {
390			if !device.Integrated {
391				filtered = append(filtered, device)
392				continue
393			}
394	
395			if explicit {
396				if allow {
397					filtered = append(filtered, device)
398					continue
399				}
400			} else if integratedGPUAllowedByDefault(device) {
401				filtered = append(filtered, device)
402				continue
403			}
404	
405			slog.Info("dropping integrated GPU; to enable, set OLLAMA_IGPU_ENABLE=1",
406				"id", device.ID,
407				"library", device.Library,
408				"compute", device.Compute(),
409				"name", device.Name,
410				"description", device.Description,
411				"pci_id", device.PCIID)
412		}
413	
414		return filtered
415	}
