438	func filterOverlapByLibrary(supported map[string]map[string]map[string]int, needsDelete []bool) {
439		// For multi-GPU systems, use the newest version that supports all the GPUs
440		for _, byLibDirs := range supported {
441			libDirs := make([]string, 0, len(byLibDirs))
442			for libDir := range byLibDirs {
443				libDirs = append(libDirs, libDir)
444			}
445			sort.Sort(sort.Reverse(sort.StringSlice(libDirs)))
446			anyMissing := false
447			var newest string
448			for _, newest = range libDirs {
449				for _, libDir := range libDirs {
450					if libDir == newest {
451						continue
452					}
453					if len(byLibDirs[newest]) != len(byLibDirs[libDir]) {
454						anyMissing = true
455						break
456					}
457					for dev := range byLibDirs[newest] {
458						if _, found := byLibDirs[libDir][dev]; !found {
459							anyMissing = true
460							break
461						}
462					}
463				}
464				if !anyMissing {
465					break
466				}
467			}
468			// Now we can mark overlaps for deletion
469			for _, libDir := range libDirs {
470				if libDir == newest {
471					continue
472				}
473				for dev, i := range byLibDirs[libDir] {
474					if _, found := byLibDirs[newest][dev]; found {
475						slog.Debug("filtering device with overlapping libraries",
476							"id", dev,
477							"library", libDir,
478							"delete_index", i,
479							"kept_library", newest,
480						)
481						needsDelete[i] = true
482					}
483				}
484			}
485		}
486	}
