488	func bootstrapDevicesWithMetalRetry(firstAttemptCtx, retryParentCtx context.Context, timeout time.Duration, ollamaLibDirs []string, extraEnvs map[string]string) []ml.DeviceInfo {
489		extraEnvs = normalizeDiscoveryEnv(ollamaLibDirs, extraEnvs)
490	
491		runDiscovery := func(ctx context.Context, extraEnvs map[string]string) ([]ml.DeviceInfo, *llm.StatusWriter, error) {
492			start := time.Now()
493			defer func() {
494				slog.Debug("bootstrap discovery took", "duration", time.Since(start), "OLLAMA_LIBRARY_PATH", ollamaLibDirs, "extra_envs", extraEnvs)
495			}()
496			return bootstrapDevicesWithStatusWatchdog(ctx, ollamaLibDirs, extraEnvs)
497		}
498	
499		devices, status, err := runDiscovery(firstAttemptCtx, extraEnvs)
500		if err == nil {
501			recordPersistentRunnerEnv(devices, extraEnvs)
502			return devices
503		}
504	
505		if llm.ShouldRetryWithMetalTensorDisabled(err, status) && (extraEnvs == nil || extraEnvs["GGML_METAL_TENSOR_DISABLE"] != "1") {
506			retryEnvs := map[string]string{}
507			for k, v := range extraEnvs {
508				retryEnvs[k] = v
509			}
510			retryEnvs["GGML_METAL_TENSOR_DISABLE"] = "1"
511			slog.Warn("retrying llama-server GPU discovery with Metal tensor API disabled", "error", err, "detail", lastDiscoveryStatusError(status))
512	
513			retryCtx, cancel := context.WithTimeout(retryParentCtx, timeout)
514			defer cancel()
515			devices, status, err = runDiscovery(retryCtx, retryEnvs)
516			if err == nil {
517				recordPersistentRunnerEnv(devices, retryEnvs)
518				return devices
519			}
520		}
521	
522		slog.Info("failure during llama-server GPU discovery", "OLLAMA_LIBRARY_PATH", ollamaLibDirs, "extra_envs", extraEnvs, "error", err, "detail", lastDiscoveryStatusError(status))
523		return devices
524	}
