531		if goos != "linux" || len(ollamaLibDirs) == 0 || !isROCmLibraryDir(filepath.Base(ollamaLibDirs[len(ollamaLibDirs)-1])) {
532			return extraEnvs
533		}
534	
535		if extraEnvs["ROCR_VISIBLE_DEVICES"] != "" || envconfig.RocrVisibleDevices() != "" {
536			return extraEnvs
537		}
538	
539		source, tokens := rocmNumericVisibleDeviceSource(extraEnvs)
540		if len(tokens) == 0 {
541			return extraEnvs
542		}
543	
544		env := make(map[string]string, len(extraEnvs)+1)
545		for k, v := range extraEnvs {
546			env[k] = v
547		}
