568	func runBootstrapDevicesWithStatusWatchdog(
569		ctx context.Context,
570		ollamaLibDirs []string,
571		extraEnvs map[string]string,
572		discover func(context.Context, []string, map[string]string) ([]ml.DeviceInfo, *llm.StatusWriter, error),
573	) ([]ml.DeviceInfo, *llm.StatusWriter, error) {
574		resultCh := make(chan bootstrapDevicesResult, 1)
575		go func() {
576			devices, status, err := discover(ctx, ollamaLibDirs, extraEnvs)
577			resultCh <- bootstrapDevicesResult{devices: devices, status: status, err: err}
578		}()
579	
580		select {
581		case result := <-resultCh:
582			return result.devices, result.status, result.err
583		case <-ctx.Done():
584			slog.Warn("llama-server GPU discovery watchdog timed out", "OLLAMA_LIBRARY_PATH", ollamaLibDirs, "extra_envs", extraEnvs, "error", ctx.Err())
585			return nil, nil, ctx.Err()
586		}
587	}
