607	func visibleDeviceFilterTokens(goos, library string) []string {
608		switch library {
609		case "CUDA":
610			return splitVisibleDeviceList(envconfig.CudaVisibleDevices())
611		case "ROCm":
612			if goos == "linux" {
613				if tokens := splitVisibleDeviceList(envconfig.RocrVisibleDevices()); len(tokens) > 0 {
614					return tokens
615				}
616				if _, tokens := rocmNumericVisibleDeviceSource(nil); len(tokens) > 0 {
617					return tokens
618				}
619				return nil
620			}
621			for _, value := range []string{envconfig.HipVisibleDevices(), envconfig.GpuDeviceOrdinal(), envconfig.CudaVisibleDevices()} {
622				if tokens := splitNumericVisibleDeviceList(value); len(tokens) > 0 {
623					return tokens
624				}
625			}
626		case "Vulkan":
627			return splitVisibleDeviceList(envconfig.VkVisibleDevices())
628		}
629	
630		return nil
631	}
