633	func rocmNumericVisibleDeviceSource(extraEnvs map[string]string) (string, []string) {
634		for _, name := range []string{"HIP_VISIBLE_DEVICES", "GPU_DEVICE_ORDINAL", "CUDA_VISIBLE_DEVICES"} {
635			value := extraEnvs[name]
636			if value == "" {
637				switch name {
638				case "HIP_VISIBLE_DEVICES":
639					value = envconfig.HipVisibleDevices()
640				case "GPU_DEVICE_ORDINAL":
641					value = envconfig.GpuDeviceOrdinal()
642				case "CUDA_VISIBLE_DEVICES":
643					value = envconfig.CudaVisibleDevices()
644				}
645			}
646			if tokens := splitNumericVisibleDeviceList(value); len(tokens) > 0 {
647				return name, tokens
648			}
649		}
650		return "", nil
651	}
652	
653	func splitVisibleDeviceList(value string) []string {
654		fields := strings.Split(value, ",")
655		tokens := make([]string, 0, len(fields))
656		for _, field := range fields {
657			field = strings.TrimSpace(field)
658			if field != "" {
659				tokens = append(tokens, field)
660			}
661		}
662		return tokens
663	}
664	
665	func splitNumericVisibleDeviceList(value string) []string {
666		tokens := splitVisibleDeviceList(value)
667		if len(tokens) == 0 {
668			return nil
669		}
670		for _, token := range tokens {
671			index, err := strconv.Atoi(token)
672			if err != nil || index < 0 {
673				return nil
674			}
675		}
676		return tokens
677	}
