694	func recordPersistentRunnerEnv(devices []ml.DeviceInfo, extraEnvs map[string]string) {
695		if extraEnvs["GGML_METAL_TENSOR_DISABLE"] != "1" {
696			return
697		}
698		for i := range devices {
699			if devices[i].Library != "Metal" {
700				continue
701			}
702			if devices[i].RunnerEnvOverrides == nil {
703				devices[i].RunnerEnvOverrides = map[string]string{}
704			}
705			devices[i].RunnerEnvOverrides["GGML_METAL_TENSOR_DISABLE"] = "1"
706		}
707	}
