709	func overrideWarnings() {
710		anyFound := false
711		m := envconfig.AsMap()
712		for _, k := range []string{
713			"CUDA_VISIBLE_DEVICES",
714			"HIP_VISIBLE_DEVICES",
715			"ROCR_VISIBLE_DEVICES",
716			"GGML_VK_VISIBLE_DEVICES",
717			"GPU_DEVICE_ORDINAL",
718			"HSA_OVERRIDE_GFX_VERSION",
719		} {
720			if e, found := m[k]; found && e.Value != "" {
721				anyFound = true
722				slog.Warn("user overrode visible devices", k, e.Value)
723			}
724		}
725		if anyFound {
726			slog.Warn("if GPUs are not correctly discovered, unset and try again")
727		}
728	}
