 23	// llamaServerDiscoveryWaitDelay bounds how long Wait can hang after we stop
 24	// the short-lived discovery subprocess.
 25	const llamaServerDiscoveryWaitDelay = 5 * time.Second
 27	// llamaServerDiscoverDevices spawns llama-server briefly (without a model) to
 28	// discover GPU devices and their capabilities. The server prints device info
 29	// and system_info (including compiled CUDA architectures) on startup before
 30	// any model load, then we kill it.
 31	//
 32	// Captured from combined stderr output:
 33	//
 34	//	Device 0: NVIDIA GeForce RTX 4060 Ti, compute capability 8.9, VMM: yes, VRAM: 16379 MiB
 35	//	Device 0: AMD Radeon RX 6700 XT, gfx1031 (0x1031), VMM: no, Wave Size: 32, VRAM: 12272 MiB
 36	//
 37	// Captured from stdout device list:
 38	//
 39	//	CUDA0: NVIDIA GeForce RTX 4060 Ti (16379 MiB, 14900 MiB free)
 40	//	Metal: Apple M3 Max (98304 MiB, 98303 MiB free)
 42	func llamaServerDiscoverDevices(ctx context.Context, libDirs []string, extraEnvs map[string]string) ([]ml.DeviceInfo, *llm.StatusWriter, error) {
 43		status := llm.NewStatusWriter(llamaServerDiscoveryOutput(ctx))
 44		llamaServer, err := llm.FindLlamaServer()
 45		if err != nil {
 46			slog.Debug("llama-server not available for device discovery", "error", err)
 47			return nil, status, err
 48		}
 50		start := time.Now()
 51		defer func() {
 52			slog.Debug("llama-server device discovery took", "duration", time.Since(start), "libDirs", libDirs)
 53		}()
 55		// Use a random port to avoid conflicts. The server may start listening
 56		// before it emits system_info, but we stop it as soon as we have the GPU
 57		// discovery output we need.
 58		port := 49152 + time.Now().UnixNano()%16383
 59		cmd := exec.CommandContext(ctx, llamaServer,
 60			"--port", strconv.FormatInt(port, 10),
 61			"--host", "127.0.0.1",
 62			"--no-webui",
 63			"--offline",
 64			"--verbose",
 65		)
 66		cmd.WaitDelay = llamaServerDiscoveryWaitDelay
 67		cmd.Env = os.Environ()
 69		llm.SetupLlamaServerCommandEnv(cmd, llamaServer, libDirs, extraEnvs)
 71		logutil.Trace("running llama-server for discovery", "cmd", cmd.Path, "libDirs", libDirs)
 73		// Capture stderr (device info + system_info) via pipe so we can
 74		// read it line-by-line and kill the server as soon as we have what we need.
 75		stderrPipe, err := cmd.StderrPipe()
 76		if err != nil {
 77			slog.Debug("llama-server discovery: failed to create stderr pipe", "error", err)
 78			return nil, status, err
 79		}
 80		// Forward stdout through the same status writer so trace logging captures
 81		// all llama-server discovery output.
 82		cmd.Stdout = status
 84		if err := cmd.Start(); err != nil {
 85			slog.Debug("llama-server discovery: failed to start", "error", err)
 86			return nil, status, err
 87		}
 89		// Read stderr until we see system_info or timeout
 90		var stderrLines []string
 91		gotSystemInfo := false
 92		done := make(chan struct{})
 93		go func() {
 94			scanner := bufio.NewScanner(stderrPipe)
 95			for scanner.Scan() {
 96				line := scanner.Text()
 97				_, _ = status.Write([]byte(line + "\n"))
 98				stderrLines = append(stderrLines, line)
 99				if strings.Contains(line, "system_info:") {
100					gotSystemInfo = true
101					break
102				}
103			}
104			close(done)
105		}()
107		select {
108		case <-done:
109		case <-ctx.Done():
110		}
112		// Kill the server - we have what we need, or timed out.
113		stoppedForDiscovery := false
114		if cmd.Process != nil {
115			stoppedForDiscovery = cmd.Process.Kill() == nil
116		}
117		waitErr := cmd.Wait()
118		if waitErr != nil {
119			exit := llm.ExitStatusFromError(waitErr)
120			if stoppedForDiscovery {
121				slog.Debug("llama-server discovery: stopped subprocess after collecting GPU info", "exit", exit, "libDirs", libDirs)
122			}
123			if !stoppedForDiscovery {
124				slog.Debug("llama-server discovery: server startup exited", "error", waitErr, "exit", exit, "libDirs", libDirs)
125			}
126		}
127		<-done
129		if ctx.Err() != nil {
130			slog.Warn("llama-server discovery: timed out waiting for server startup", "error", ctx.Err(), "libDirs", libDirs, "lines_captured", len(stderrLines))
131			return nil, status, ctx.Err()
132		}
134		if !gotSystemInfo {
135			slog.Warn("llama-server discovery: system_info line not found in output - "+
136				"CUDA architecture filtering will be disabled. If GPU inference fails, "+
137				"this may indicate an incompatible llama-server version.",
138				"libDirs", libDirs, "lines_captured", len(stderrLines))
139		}
141		// Also run --list-devices to get the stdout device list with free memory
142		// (the brief server startup doesn't print that)
143		cmd2 := exec.CommandContext(ctx, llamaServer, "--list-devices", "--offline", "--verbose")
144		cmd2.WaitDelay = llamaServerDiscoveryWaitDelay
145		cmd2.Env = cmd.Env // reuse same environment
146		listOutput, err := cmd2.CombinedOutput()
147		_, _ = status.Write(listOutput)
148		if err != nil {
149			exit := llm.ExitStatusFromError(err)
150			slog.Debug("llama-server --list-devices failed", "error", err, "exit", exit)
151			if exit.Known() {
152				return nil, status, fmt.Errorf("llama-server --list-devices failed: %s", exit)
153			}
154			return nil, status, fmt.Errorf("llama-server --list-devices failed: %w", err)
155		}
157		nativeDevices, nativeStderr, nativeErr := discoverNativeDevices(ctx, llamaServer, libDirs, extraEnvs)
158		_, _ = status.Write([]byte(nativeStderr))
159		if nativeErr != nil {
160			logNativeProbeFailure(nativeErr, nativeStderr, libDirs)
161		}
163		llamaOutput := string(listOutput) + "\n" + strings.Join(stderrLines, "\n")
164		return parseLlamaServerDevicesWithNative(llamaOutput, nativeStderr, libDirs, nativeDevices), status, nil
165	}
167	func llamaServerDiscoveryOutput(ctx context.Context) io.Writer {
168		if slog.Default().Enabled(ctx, logutil.LevelTrace) {
169			return os.Stderr
170		}
171		return io.Discard
172	}
174	// deviceLineRegex matches stdout lines like:
175	//
176	//	CUDA0: NVIDIA GeForce RTX 4060 Ti (16379 MiB, 14900 MiB free)
177	//	Metal: Apple M3 Max (98304 MiB, 98303 MiB free)
178	var deviceLineRegex = regexp.MustCompile(
179		`^\s+(.+?):\s+(.+?)\s+\((\d+)\s+MiB,\s+(\d+)\s+MiB\s+free\)`,
180	)
182	// cudaCCRegex matches CUDA stderr lines like:
183	//
184	//	Device 0: NVIDIA GeForce GTX 1060 6GB, compute capability 6.1, VMM: yes, VRAM: 6063 MiB
185	var cudaCCRegex = regexp.MustCompile(
186		`Device\s+(\d+):.*compute capability\s+(\d+)\.(\d+)`,
187	)
189	// cudaArchsRegex matches the CUDA architecture list from system_info like:
190	//
191	//	CUDA : ARCHS = 750,800,860,890,900,1000,1030,1100,1200,1210
192	var cudaArchsRegex = regexp.MustCompile(
193		`CUDA\s*:\s*ARCHS\s*=\s*([\d,]+)`,
194	)
196	var (
197		cudaRuntimeSORegex  = regexp.MustCompile(`^libcudart\.so\.(\d+)(?:\.(\d+))?`)
198		cudaRuntimeDLLRegex = regexp.MustCompile(`^cudart64_(\d{2})(\d)\.dll$`)
199		cudaRuntimeDirRegex = regexp.MustCompile(`^cuda_v(\d+)$`)
200	)
202	// parseLlamaServerDevicesWithNative parses the combined output of llama-server
203	// discovery. It extracts device info, ROCm gfx targets, CUDA compute
204	// capabilities, and CUDA compiled architecture lists.
205	func parseLlamaServerDevicesWithNative(output, nativeOutput string, libDirs []string, nativeDevices []nativeProbeDevice) []ml.DeviceInfo {
206		combined := output
207		if nativeOutput != "" {
208			combined += "\n" + nativeOutput
209		}
210		// Extract per-device metadata from stderr
211		gfxByIndex := parseROCmGFXTargets(combined)
212		rocmGFXOverride := hsaOverrideGFXTarget()
213		// The native probe enumerates Vulkan devices in its own order, which can
214		// differ from llama-server's, so its ggml_vulkan uma lines must not key
215		// into llama-server's device indexes.
216		integratedByIndex := parseVulkanUMA(output)
217		ccByIndex := make(map[int]cudaComputeCapability)
218		var cudaArchs []string // compiled architectures for this variant
219		nativeByIndex := nativeProbeByLibraryIndex(nativeDevices)
220		for idx, dev := range nativeByIndex["ROCm"] {
221			if rocmGFXOverride != "" {
222				gfxByIndex[idx] = rocmGFXOverride
223			} else if dev.GFXTarget != "" {
224				gfxByIndex[idx] = dev.GFXTarget
225			}
226		}
228		scanner := bufio.NewScanner(strings.NewReader(combined))
229		for scanner.Scan() {
230			line := scanner.Text()
231			if matches := cudaCCRegex.FindStringSubmatch(line); matches != nil {
232				idx, _ := strconv.Atoi(matches[1])
233				major, _ := strconv.Atoi(matches[2])
234				minor, _ := strconv.Atoi(matches[3])
235				ccByIndex[idx] = cudaComputeCapability{
236					major: major,
237					minor: minor,
238					arch:  fmt.Sprintf("%d%d0", major, minor),
239				}
240			}
241			if matches := cudaArchsRegex.FindStringSubmatch(line); matches != nil {
242				cudaArchs = strings.Split(matches[1], ",")
243			}
244		}
245		if cudaDevices := nativeByIndex["CUDA"]; len(cudaDevices) > 0 {
246			for idx, dev := range cudaDevices {
247				if dev.ComputeMajor <= 0 {
248					continue
249				}
250				ccByIndex[idx] = cudaComputeCapability{
251					major: dev.ComputeMajor,
252					minor: dev.ComputeMinor,
253					arch:  fmt.Sprintf("%d%d0", dev.ComputeMajor, dev.ComputeMinor),
254				}
255			}
256		}
258		// Validate CUDA devices against compiled architectures
259		cudaArchSet := make(map[string]bool, len(cudaArchs))
260		for _, arch := range cudaArchs {
261			cudaArchSet[strings.TrimSpace(arch)] = true
262		}
263		cudaRuntimeMajor, cudaRuntimeMinor, hasCUDARuntime := cudaRuntimeVersion(libDirs)
265		// Parse stdout device lines
266		var devices []ml.DeviceInfo
267		deviceIndex := 0
268		scanner = bufio.NewScanner(strings.NewReader(output))
269		for scanner.Scan() {
270			matches := deviceLineRegex.FindStringSubmatch(scanner.Text())
271			if matches == nil {
272				continue
273			}
275			name := matches[1]
276			description := matches[2]
277			totalMiB, _ := strconv.ParseUint(matches[3], 10, 64)
278			freeMiB, _ := strconv.ParseUint(matches[4], 10, 64)
279			library := inferLibrary(name, description)
281			// Skip pseudo-devices like BLAS/Accelerate that report zero memory.
282			// These are CPU math libraries, not real GPUs — they shouldn't appear
283			// as inference compute devices or inflate the scheduler's GPU count.
284			if totalMiB == 0 {
285				slog.Debug("skipping pseudo-device with zero memory", "name", name, "description", description)
286				deviceIndex++
287				continue
288			}
290			// For CUDA devices, check if this variant supports the device's CC
291			if library == "CUDA" {
292				cc, ok := ccByIndex[deviceIndex]
293				if ok && len(cudaArchSet) > 0 {
294					if !cudaArchSet[cc.arch] {
295						slog.Info("skipping CUDA device — compute capability not in compiled architectures",
296							"device", description, "cc", cc.arch, "archs", cudaArchs,
297							"libDirs", libDirs)
298						deviceIndex++
299						continue
300					}
301				} else if !ok {
302					slog.Warn("llama-server discovery: could not determine compute capability for CUDA device — "+
303						"architecture filtering disabled for this device. If inference crashes, "+
304						"check that the CUDA backend supports this GPU.",
305						"device", description, "libDirs", libDirs)
306				} else if len(cudaArchSet) == 0 {
307					slog.Warn("llama-server discovery: could not determine compiled CUDA architectures — "+
308						"architecture filtering disabled. If inference crashes on older GPUs, "+
309						"check llama-server system_info output for ARCHS.",
310						"device", description, "libDirs", libDirs)
311				}
312			}
314			nativeDevice, hasNativeDevice := nativeByIndex[library][deviceIndex]
315			totalBytes := totalMiB * 1024 * 1024
316			if hasNativeDevice && !nativeProbeMatchesLlamaServerDevice(library, description, totalBytes, nativeDevice) {
317				hasNativeDevice = false
318			}
319			computeMajor, computeMinor := computeVersion(library, deviceIndex, gfxByIndex, ccByIndex)
320			dev := ml.DeviceInfo{
321				DeviceID: ml.DeviceID{
322					ID:      strconv.Itoa(deviceIndex),
323					Library: library,
324				},
325				Name:         name,
326				Description:  description,
327				TotalMemory:  totalBytes,
328				FreeMemory:   freeMiB * 1024 * 1024,
329				ComputeMajor: computeMajor,
330				ComputeMinor: computeMinor,
331				LibraryPath:  libDirs,
332				GFXTarget:    gfxByIndex[deviceIndex],
333				Integrated:   isIntegratedLlamaServerDevice(library, deviceIndex, integratedByIndex),
334			}
335			if hasNativeDevice {
336				if nativeDevice.DeviceID != "" {
337					dev.PCIID = nativeDevice.DeviceID
338				}
339				if nativeDevice.IntegratedKnown {
340					dev.Integrated = nativeDevice.Integrated
341				} else {
342					dev.Integrated = dev.Integrated || nativeDevice.Integrated
343				}
344				if dev.ComputeMajor == 0 && nativeDevice.ComputeMajor > 0 {
345					dev.ComputeMajor = nativeDevice.ComputeMajor
346					dev.ComputeMinor = nativeDevice.ComputeMinor
347				}
348				if nativeDevice.CUDADriverMajor > 0 {
349					dev.DriverMajor = nativeDevice.CUDADriverMajor
350					dev.DriverMinor = nativeDevice.CUDADriverMinor
351				}
352				if nativeDevice.NVIDIADriverMajor > 0 {
353					dev.NVIDIADriverMajor = nativeDevice.NVIDIADriverMajor
354				}
355				setROCmGFXTarget(&dev, nativeDevice.GFXTarget)
356			}
357			setROCmGFXTarget(&dev, rocmGFXOverride)
358			if library == "CUDA" && dev.DriverMajor == 0 && hasCUDARuntime {
359				dev.DriverMajor = cudaRuntimeMajor
360				dev.DriverMinor = cudaRuntimeMinor
361			}
363			devices = append(devices, dev)
364			deviceIndex++
365		}
367		return refineLlamaServerDevices(devices, libDirs)
368	}
370	func nativeProbeMatchesLlamaServerDevice(library, description string, totalBytes uint64, nativeDevice nativeProbeDevice) bool {
371		if library != "Vulkan" {
372			return true
373		}
375		nativeDescription := nativeDevice.Description
376		if nativeDescription == "" {
377			nativeDescription = nativeDevice.Name
378		}
379		if nativeDescription == "" || !ml.SimilarDeviceDescription(description, nativeDescription) {
380			slog.Debug("skipping Vulkan native metadata with mismatched device name",
381				"llama_server_name", description,
382				"native_name", nativeDescription)
383			return false
384		}
385		if nativeDevice.TotalMemory != 0 && !ml.SimilarDeviceMemory(totalBytes, nativeDevice.TotalMemory) {
386			slog.Debug("skipping Vulkan native metadata with mismatched memory",
387				"llama_server_name", description,
388				"llama_server_total", totalBytes,
389				"native_total", nativeDevice.TotalMemory)
390			return false
391		}
393		return true
394	}
396	func cudaRuntimeVersion(libDirs []string) (int, int, bool) {
397		bestMajor, bestMinor := -1, -1
398		update := func(major, minor int) {
399			if major > bestMajor || (major == bestMajor && minor > bestMinor) {
400				bestMajor, bestMinor = major, minor
401			}
402		}
404		for _, dir := range libDirs {
405			for _, entry := range readDirNames(dir) {
406				if matches := cudaRuntimeSORegex.FindStringSubmatch(entry); matches != nil {
407					major, _ := strconv.Atoi(matches[1])
408					minor := 0
409					if matches[2] != "" {
410						minor, _ = strconv.Atoi(matches[2])
411					}
412					update(major, minor)
413				}
414				if matches := cudaRuntimeDLLRegex.FindStringSubmatch(entry); matches != nil {
415					major, _ := strconv.Atoi(matches[1])
416					minor, _ := strconv.Atoi(matches[2])
417					update(major, minor)
418				}
419			}
421			if matches := cudaRuntimeDirRegex.FindStringSubmatch(filepath.Base(dir)); matches != nil {
422				major, _ := strconv.Atoi(matches[1])
423				update(major, 0)
424			}
425		}
427		if bestMajor < 0 {
428			return 0, 0, false
429		}
430		return bestMajor, bestMinor, true
431	}
433	func readDirNames(dir string) []string {
434		entries, err := os.ReadDir(dir)
435		if err != nil {
436			return nil
437		}
438		names := make([]string, 0, len(entries))
439		for _, entry := range entries {
440			names = append(names, entry.Name())
441		}
442		return names

